const CACHE = "mentora-shell-v3";
const SHELL = ["/", "/index.html", "/manifest.webmanifest"];

self.addEventListener("install", (event) => {
  event.waitUntil((async () => {
    const cache = await caches.open(CACHE);
    const manifest = await fetch("/offline-assets.json", { cache: "no-store" });
    // The manifest is generated by Vite for built deployments only.
    const assets = manifest.ok && manifest.headers.get("content-type")?.includes("application/json")
      ? await manifest.json() : [];
    await cache.addAll([...SHELL, ...assets]);
    await self.skipWaiting();
  })());
});

self.addEventListener("activate", (event) => {
  event.waitUntil((async () => {
    const keys = await caches.keys();
    await Promise.all(keys.filter((key) => key.startsWith("mentora-shell-") && key !== CACHE).map((key) => caches.delete(key)));
    await self.clients.claim();
  })());
});

self.addEventListener("fetch", (event) => {
  const request = event.request;
  const url = new URL(request.url);
  if (request.method !== "GET" || url.origin !== self.location.origin || url.pathname.startsWith("/api/")) return;

  event.respondWith((async () => {
    const isBuiltAsset = url.pathname.startsWith("/assets/");
    if (isBuiltAsset) {
      const cache = await caches.open(CACHE);
      // The same public build asset can be fetched with different Origin headers.
      const cached = await cache.match(request, { ignoreVary: true });
      if (cached) return cached;
    }
    try {
      const response = await fetch(request);
      if (response.ok && request.mode !== "navigate") {
        const copy = response.clone();
        try {
          const cache = await caches.open(CACHE);
          await cache.put(request, copy);
        } catch {
          // A storage failure must not interrupt an online request.
        }
      }
      return response;
    } catch {
      const cache = await caches.open(CACHE);
      return (await cache.match(request.mode === "navigate" ? "/index.html" : request)) ?? Response.error();
    }
  })());
});
